"use client";

import {
  createContext,
  useContext,
  useState,
  type ReactNode,
} from "react";

import { cn } from "@/lib/utils";

type DropdownContextValue = {
  open: boolean;
  toggle: () => void;
  close: () => void;
};

const DropdownContext = createContext<DropdownContextValue | null>(null);

export function DropdownMenu({ children }: { children: ReactNode }) {
  const [open, setOpen] = useState(false);

  return (
    <DropdownContext.Provider
      value={{
        open,
        toggle: () => setOpen((current) => !current),
        close: () => setOpen(false),
      }}
    >
      <div className="relative">{children}</div>
    </DropdownContext.Provider>
  );
}

export function DropdownMenuTrigger({ children }: { children: ReactNode }) {
  const context = useContext(DropdownContext);

  if (!context) {
    throw new Error("DropdownMenuTrigger must be used inside DropdownMenu");
  }

  return (
    <span
      className="cursor-pointer"
      onClick={context.toggle}
      role="presentation"
    >
      {children}
    </span>
  );
}

export function DropdownMenuContent({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  const context = useContext(DropdownContext);

  if (!context || !context.open) {
    return null;
  }

  return (
    <div
      className={cn(
        "absolute right-0 z-20 mt-2 min-w-44 rounded-md border border-border bg-card p-1 shadow-lg",
        className,
      )}
    >
      {children}
    </div>
  );
}

export function DropdownMenuItem({
  children,
  disabled,
  onClick,
  destructive,
}: {
  children: ReactNode;
  disabled?: boolean;
  onClick?: () => void;
  destructive?: boolean;
}) {
  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      className={cn(
        "block min-h-9 w-full cursor-pointer rounded px-3 py-2 text-left text-sm",
        destructive
          ? "text-red-600 hover:bg-red-50"
          : "text-primary hover:bg-primary/5",
        "disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-60",
      )}
    >
      {children}
    </button>
  );
}

export function DropdownMenuSeparator() {
  return <div className="my-1 h-px bg-border" />;
}
